<!doctype html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>新中市入岛居民信息登记</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@300;400;500;700&display=swap');

        :root {
            --bg-gradient-start: #e0f2fe;
            --bg-gradient-end: #bae6fd;
            --card-bg: rgba(255, 255, 255, 0.75);
            --text-main: #0c4a6e;
            --text-light: #0284c7;
            --border-color: #7dd3fc;
            --accent-color: #0284c7;
            --accent-hover: #0369a1;
            --input-bg: rgba(255, 255, 255, 0.9);
            --font-main: 'Noto Sans SC', sans-serif;
        }

        * { box-sizing: border-box; }

        body {
            font-family: var(--font-main);
            background: linear-gradient(135deg, var(--bg-gradient-start) 0%, var(--bg-gradient-end) 100%);
            color: var(--text-main);
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            margin: 0;
            padding: 2rem 1rem;
            overflow: auto;
        }

        .generator-container {
            background-color: var(--card-bg);
            backdrop-filter: blur(16px);
            -webkit-backdrop-filter: blur(16px);
            border: 1px solid rgba(255, 255, 255, 0.6);
            border-radius: 24px;
            box-shadow: 0 20px 40px rgba(2, 132, 199, 0.1), inset 0 0 0 1px rgba(255, 255, 255, 0.5);
            width: 100%;
            max-width: 800px;
            padding: 3.5rem 4.5rem;
            position: relative;
        }

        /* ═══ 2026-10-12 落印序列：
           居委会印章落印 → 信封上下合拢（封口在上部 1/6）
           → 红色「档案已盖章归档」横跨封口 → 海关章居中透明底缓缓盖下 ═══ */
        .envbox { position: relative; width: 580px; max-width: 88%; height: 330px; margin: 0 auto; perspective: 1200px; }
        .env { position: absolute; inset: 0; border-radius: 12px;
            background: linear-gradient(180deg,#efe8d8,#faf6ec);
            box-shadow: 0 16px 40px rgba(15,23,42,.16), inset 0 0 0 1px rgba(120,110,80,.20);
            overflow: hidden; }
        .flapBot { position: absolute; left: 0; right: 0; bottom: 0; height: 83.4%; z-index: 1;
            background: linear-gradient(0deg,#faf6ec,#f3eddf);
            box-shadow: 0 -3px 10px rgba(90,80,55,.14); transform-origin: 50% 100%;
            animation: hpFlapBot .9s cubic-bezier(.3,.9,.3,1) .25s both; }
        .flapTop { position: absolute; left: 0; right: 0; top: 0; height: 16.6%; z-index: 3;
            border-radius: 12px 12px 0 0;
            background: linear-gradient(180deg,#f4eee1,#ece4d2);
            box-shadow: 0 7px 16px rgba(90,80,55,.26); transform-origin: 50% 0;
            animation: hpFlapTop .9s cubic-bezier(.3,.9,.3,1) .4s both; }
        .seam { position: absolute; left: 0; right: 0; top: 16.6%; height: 2px; margin-top: -1px; z-index: 4;
            background: repeating-linear-gradient(90deg,rgba(120,110,80,.34) 0 8px,transparent 8px 16px);
            opacity: 0; animation: hpFadeIn .3s ease 1.25s both; }
        .stitle { position: absolute; left: 0; right: 0; top: 16.6%; z-index: 5;
            transform: translateY(-50%); text-align: center;
            color: #c8102e; font-weight: 900; font-size: 1.95rem; letter-spacing: 16px;
            text-indent: 16px; white-space: nowrap;
            text-shadow: 0 1px 0 rgba(255,255,255,.85), 0 2px 6px rgba(200,16,46,.18);
            opacity: 0; animation: hpTitleIn .5s cubic-bezier(.3,1.25,.5,1) 1.45s both; }
        .stwrap { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
            z-index: 40; pointer-events: none; }
        .airport { width: 52%; height: auto; display: block; opacity: 0;
            transform: rotate(-18deg) scale(1.45);
            filter: drop-shadow(0 12px 24px rgba(12,74,110,.18));
            animation: hpAirportDown 5s cubic-bezier(.25,.8,.35,1) 1.85s forwards; }
        @keyframes hpFlapBot { 0%{transform:rotateX(92deg)} 70%{transform:rotateX(-7deg)} 100%{transform:rotateX(0)} }
        @keyframes hpFlapTop { 0%{transform:rotateX(-92deg)} 70%{transform:rotateX(7deg)} 100%{transform:rotateX(0)} }
        @keyframes hpFadeIn { 0%{opacity:0} 100%{opacity:1} }
        @keyframes hpTitleIn { 0%{opacity:0;transform:translateY(-50%) scale(.90)} 100%{opacity:1;transform:translateY(-50%) scale(1)} }
        @keyframes hpAirportDown {
            0%   { opacity: 0;   transform: rotate(-18deg)   scale(1.45); }
            8%   { opacity: .30; transform: rotate(-17.3deg) scale(1.42); }
            40%  { opacity: 1;   transform: rotate(-15.2deg) scale(1.05); }
            55%  {               transform: rotate(-14.4deg) scale(.99); }
            70%  {               transform: rotate(-14deg)   scale(1.005); }
            85%  {               transform: rotate(-14deg)   scale(.998); }
            100% { opacity: 1;   transform: rotate(-14deg)   scale(1); }
        }
        /* 居委会印章的落印（2.6s） */
        /* 2026-10-12：印章的点击动画保持原样（:hover 抬起 / :active 按下回正）
           松手即盖下，不再外加落印动画 */
        .stamp span {
            display: block;
            color: #ef4444;
            font-size: 0.75rem;
            margin-top: 4px;
            letter-spacing: 2px;
            text-align: center;
        }

        .screen { display: none; }
        .screen.active {
            display: block;
            animation: slideUpFade 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }

        @keyframes slideUpFade {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .screen-header {
            text-align: left;
            margin-bottom: 2.5rem;
            padding-bottom: 1rem;
            position: relative;
            display: flex;
            flex-direction: column;
            gap: 0.3rem;
        }

        .screen-header h2 {
            font-size: 2rem;
            margin: 0;
            font-weight: 700;
            color: var(--text-main);
            display: inline-block;
        }

        .screen-header p {
            color: #ffffff;
            background-color: var(--text-light);
            display: inline-block;
            padding: 4px 12px;
            border-radius: 20px;
            font-size: 0.85rem;
            letter-spacing: 1px;
            margin: 0;
            align-self: flex-start;
        }

        .nav-buttons {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: 3.5rem;
            gap: 1rem;
            padding-top: 1rem;
        }

        .btn {
            font-family: var(--font-main);
            padding: 0.8rem 2.2rem;
            border-radius: 50px;
            border: none;
            background: rgba(255, 255, 255, 0.8);
            cursor: pointer;
            font-size: 1.05rem;
            letter-spacing: 1px;
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            color: var(--accent-color);
            font-weight: 600;
            box-shadow: 0 4px 10px rgba(0,0,0,0.05);
        }

        .btn-primary {
            background-color: var(--accent-color);
            color: #fff;
            box-shadow: 0 4px 15px rgba(2, 132, 199, 0.3);
        }

        .btn:hover:not(:disabled) {
            transform: translateY(-3px);
            box-shadow: 0 8px 20px rgba(2, 132, 199, 0.25);
        }

        .btn-primary:hover:not(:disabled) {
            background-color: var(--accent-hover);
        }

        .btn:disabled {
            opacity: 0.5;
            cursor: not-allowed;
            background: #e2e8f0;
            color: #94a3b8;
            box-shadow: none;
        }

        /* ---------------- 印章与外框样式 ---------------- */
        .stamp-container {
            border: 1px solid #ef4444; 
            padding: 15px;
            background: transparent;
            display: flex;
            justify-content: center;
            align-items: center;
            width: 200px;
            height: 200px;
            margin-left: auto; 
        }

        .stamp-btn {
            width: 170px;
            height: 170px;
            border-radius: 50%;
            border: none;
            background-color: transparent;
            cursor: pointer;
            padding: 0;
            transition: all 0.15s ease-out;
            transform: rotate(-12deg); 
            opacity: 0.85;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .stamp-btn:hover {
            transform: rotate(-12deg) scale(1.05);
            opacity: 1;
            filter: drop-shadow(0 8px 15px rgba(220, 38, 38, 0.25));
        }

        .stamp-btn:active {
            transform: rotate(0deg) scale(0.95);
            filter: drop-shadow(0 2px 5px rgba(220, 38, 38, 0.3));
        }

        .seal-svg {
            width: 100%;
            height: 100%;
        }

        /* ---------------- 前端页面自身的加载抖动动画 ---------------- */
        @keyframes jitter {
            0% { transform: translate(1px, 1px) rotate(0deg); }
            10% { transform: translate(-1px, -2px) rotate(-1deg); }
            20% { transform: translate(-3px, 0px) rotate(1deg); }
            30% { transform: translate(3px, 2px) rotate(0deg); }
            40% { transform: translate(1px, -1px) rotate(1deg); }
            50% { transform: translate(-1px, 2px) rotate(-1deg); }
            60% { transform: translate(-2px, 1px) rotate(0deg); }
            70% { transform: translate(2px, 1px) rotate(-1deg); }
            80% { transform: translate(-1px, -1px) rotate(1deg); }
            90% { transform: translate(1px, 2px) rotate(0deg); }
            100% { transform: translate(1px, -2px) rotate(-1deg); }
        }

        .jitter-text {
            display: inline-block;
            animation: jitter 0.4s infinite;
        }

        .input-group {
            margin-bottom: 1.8rem;
            display: flex;
            flex-direction: column;
            gap: 0.6rem;
        }

        .input-group label {
            color: var(--text-main);
            font-size: 1rem;
            font-weight: 600;
            display: flex;
            align-items: center;
            padding-left: 10px;
            border-left: 4px solid var(--accent-color);
            border-radius: 2px;
            line-height: 1.2;
        }

        .input-field, .textarea-field, .select-field {
            width: 100%;
            background-color: var(--input-bg);
            border: 2px solid transparent;
            border-radius: 12px;
            padding: 0.8rem 1rem;
            color: var(--text-main);
            font-family: var(--font-main);
            font-size: 1rem;
            transition: all 0.2s ease;
            box-shadow: inset 0 2px 4px rgba(0,0,0,0.02);
        }

        .textarea-field {
            min-height: 100px;
            resize: vertical;
        }

        .input-field:focus, .textarea-field:focus, .select-field:focus {
            outline: none;
            border-color: var(--border-color);
            background-color: #fff;
            box-shadow: 0 0 0 4px rgba(2, 132, 199, 0.1);
        }

        .input-field::placeholder, .textarea-field::placeholder {
            color: #94a3b8;
            font-weight: 300;
        }

        .select-field {
            appearance: none;
            background-image: url('data:image/svg+xml;charset=US-ASCII,%3Csvg%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20width%3D%2224%22%20height%3D%2224%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%230284c7%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpolyline%20points%3D%226%209%2012%2015%2018%209%22%3E%3C/polyline%3E%3C/svg%3E');
            background-repeat: no-repeat;
            background-position: right 1rem center;
            background-size: 1em;
            padding-right: 2.5rem;
            cursor: pointer;
        }

        details summary {
            list-style: none;
        }
        details summary::-webkit-details-marker {
            display: none;
        }
        details[open] summary {
            margin-bottom: 10px;
            color: var(--accent-hover);
        }

        @media (max-width: 768px) {
            .generator-container { padding: 2rem; border-radius: 16px; }
            .screen-header h2 { font-size: 1.6rem; }
            .nav-buttons { flex-direction: column-reverse; gap: 1.5rem; }
            .btn { width: 100%; }
            /* 2026-10-12：手机上也要显示落印，不再隐藏 */
            .stamp-container { margin: 0 auto; }
        }
    </style>
</head>
<body>
    <div class="generator-container">

        <!-- 第1页: 基本信息 -->
        <div id="screen-appearance" class="screen active">
            <div class="screen-header">
                <h2>基本信息</h2>
                <p>新中市居民入岛建档</p>
            </div>
            <div class="input-group">
                <label for="char-name">姓名</label>
                <div style="display:flex;gap:8px;align-items:stretch">
                    <input type="text" id="char-name" class="input-field" placeholder="请输入姓名" style="flex:1">
                    <button type="button" id="char-lookup" style="flex:0 0 auto;background:rgba(12,74,110,.88);color:#fff;border:0;border-radius:10px;padding:0 16px;font-size:14px;font-weight:700;cursor:pointer;white-space:nowrap">🔍 查重名</button>
                </div>
                <div id="char-lookup-hint" style="font-size:0.78rem;color:#64748b;margin-top:6px;line-height:1.6">填好姓名后点「查重名」——若这个名字在世界书里已存在（即你要玩的是一个已有角色），会提示你更名或改用对应开局。</div>
            </div>
<div class="input-group">
                <label for="char-race">种族</label>
                <input type="text" placeholder="如：人类 / 魔族 / 精灵（留空按人类）" id="char-name" class="input-field" placeholder="请输入姓名">
            </div>
            <div class="input-group">
                <label for="char-gender">性别</label>
                <select id="char-gender" class="select-field">
                    <option value="">-- 请选择性别 --</option>
                    <option value="男">男</option>
                    <option value="女">女</option>
                </select>
            </div>
            <div class="input-group">
                <label for="char-age">年龄</label>
                <input type="number" id="char-age" class="input-field" placeholder="请输入年龄" min="0">
