            <div class="input-group">
                <label for="char-appearance">外貌情况</label>
                <textarea id="char-appearance" class="textarea-field" placeholder="详细描述面部特征、发型、身高、体重等体态特征。"></textarea>
            </div>
            <div class="nav-buttons">
                <span></span>
                <button id="to-property" class="btn btn-primary" disabled>下一步</button>
            </div>
        </div>

        <!-- 第2页: 基本情况 -->
        <div id="screen-property" class="screen">
            <div class="screen-header">
                <h2>家庭背景</h2>
                <p>家庭情况与关联设定</p>
            </div>
            <div class="input-group">
                <label for="char-family">家庭情况</label>
                <input type="text" id="char-family" class="input-field" placeholder="例如：富二代、官二代、普通工薪家庭、贫困生等。">
            </div>
            <div class="input-group">
                <label for="char-background">家族 / 企业隶属（选填）</label>
                <input type="text" id="char-background" class="input-field" placeholder="只在与某个家族或企业有隶属关系时填（如：林家旁支、玲雅集团员工）。没有就留空——不要在这里重复上面「家庭情况」。">
            </div>
            <div class="input-group">
                <label for="char-age-group">当前年龄段</label>
                <input type="text" id="char-age-group" class="input-field" readonly placeholder="由年龄自动判定" style="background:rgba(240,248,255,0.9);cursor:not-allowed">
                <div class="hint" id="age-group-hint" style="font-size:0.78rem;color:#64748b;margin-top:4px">按上面的「年龄」自动判定，跳级可往上调一档</div>
            </div>
<div class="input-group">
                <label for="char-is-student">是否在校学生</label>
                <select id="char-is-student" class="select-field">
                    <option value="否">否 —— 社会人 / 幼儿园以下 / 已毕业</option>
                    <option value="是">是 —— 在国立学校就读</option>
                </select>
            </div>
            <div class="input-group" id="grade-class-row" style="display:none">
                <label for="char-grade">年级</label>
                <select id="char-grade" class="select-field"><option value="初一">初一</option><option value="初二">初二</option><option value="初三">初三</option><option value="高一">高一</option><option value="高二">高二</option><option value="高三">高三</option><option value="大一">大一</option><option value="大二">大二</option><option value="大三">大三</option><option value="大四">大四</option></select>
            </div>
            <div class="input-group" id="grade-class-row2" style="display:none">
                <label for="char-class">班级</label>
                <select id="char-class" class="select-field"><option value="A班">A班</option><option value="B班">B班</option><option value="C班">C班</option><option value="D班">D班</option><option value="E班">E班</option><option value="F班">F班</option><option value="G班">G班</option><option value="H班">H班</option><option value="I班">I班</option><option value="J班">J班</option><option value="K班">K班</option><option value="L班">L班</option></select>
            </div>
            <div class="input-group">
                <label for="char-occupation">职业</label>
