            </div>
<div class="input-group">
                <label for="char-club">第一社团（选填）</label>
                <input type="text" id="char-club" class="input-field" placeholder="如：侍奉部 / 网球部">
                <select id="char-office" class="select-field" style="margin-top:6px">
                    <option value="">（未参加）</option>
                    <option value="普通成员">职务：普通成员</option>
                    <option value="部长">职务：部长</option>
                    <option value="副部长">职务：副部长</option>
                    <option value="书记">职务：书记</option>
                    <option value="顾问">职务：顾问</option>
                </select>
            </div>
            <div class="input-group">
                <label for="char-club2">第二社团（选填，最多两个）</label>
                <input type="text" id="char-club2" class="input-field" placeholder="如：文学社（没有就留空）">
                <select id="char-office2" class="select-field" style="margin-top:6px">
                    <option value="">（未参加）</option>
                    <option value="普通成员">职务：普通成员</option>
                    <option value="部长">职务：部长</option>
                    <option value="副部长">职务：副部长</option>
                    <option value="书记">职务：书记</option>
                    <option value="顾问">职务：顾问</option>
                </select>
            </div>
            <div class="input-group">
                <label for="char-residence">居住地</label>
                <select id="char-residence" class="select-field">
                    <option value="自建房区">自建房区（普通独户，最常见）</option>
                    <option value="山海雅苑">山海雅苑（顶级别墅社区）</option>
                    <option value="明日之墅">明日之墅（高端别墅区）</option>
                    <option value="红叶庄">红叶庄（普通公寓）</option>
                    <option value="平安公寓">平安公寓</option>
                    <option value="千年公寓">千年公寓</option>
                    <option value="樱花庄">樱花庄（学校廉租房）</option>
                    <option value="玲雅集团顶楼">玲雅集团顶楼</option>
                    <option value="林家宅邸">林家宅邸（需与林家有关系）</option>
                    <option value="无固定居所">无固定居所（流浪 / 借住 / 睡网吧）</option>
                </select>
