            <div class="nav-buttons">
                <button class="btn back-btn" data-target="screen-appearance">返回</button>
                <button id="to-relation" class="btn btn-primary">下一步</button>
            </div>
        </div>

        <!-- 第3页: 个人关系 -->
        <div id="screen-relation" class="screen">
            <div class="screen-header">
                <h2>社会关系</h2>
                <p>记录在岛期间的人际脉络</p>
            </div>

            <div class="input-group">
                <label for="char-other-relations">人际关系（每行一条，格式：对方姓名 · 关系 · 亲密度）</label>
                <textarea id="char-other-relations" class="textarea-field" rows="5" placeholder="例：
林雪乃 · 同班同学兼侍奉部同事 · 普通
楚凌龄 · 表姐 · 亲近
桐崎华 · 见过两次的邻居 · 脸熟
（不清楚或没有就留空，AI 会按世界书已有的关系走）"></textarea>
            </div>

            <div class="nav-buttons">
                <button class="btn back-btn" data-target="screen-property">返回</button>
                <button id="to-sexuality" class="btn btn-primary">下一步</button>
            </div>
        </div>

        <!-- 第4页: 性方面 -->
        <div id="screen-sexuality" class="screen">
            <div class="screen-header">
                <h2>私密特质</h2>
                <p>受新中市隐私法案保护</p>
            </div>
