                <label for="char-genital-data" id="genital-label">生殖器数据</label>
                <textarea id="char-genital-data" class="textarea-field" placeholder="描述尺寸、外观等特征。" data-ph-male="如：尺寸、包皮、颜色等。" data-ph-female="如：形状、颜色、阴毛浓密程度、是否有过经历等。"></textarea>
            </div>
