        <!-- 第5页: 剧情 -->
        <div id="screen-scenario" class="screen">
            <div class="screen-header">
                <h2>开启美好生活</h2>
                <p>界定档案起始的时间与环境</p>
            </div>
            <div class="input-group" style="margin-bottom: 2rem;">
                <label for="scenario-initial">开局情境</label>
                <button type="button" id="scenario-random" class="oszBack" style="margin:0 0 8px;display:inline-block;background:rgba(12,74,110,.88);color:#fff;border:0;border-radius:999px;padding:7px 16px;font-size:13px;cursor:pointer">🎲 随机生成一段（可在上面修改或全删重写）</button>
                <textarea id="scenario-initial" class="textarea-field" placeholder="你想在哪里登场？遇到了什么事？留空则随机安排。"></textarea>
            </div>

            <div class="nav-buttons" style="align-items: flex-end;">
                <button class="btn back-btn" data-target="screen-sexuality" style="margin-bottom: 20px;">返回</button>

                <div class="stamp-container">
                    <button id="start-game" class="stamp-btn">
                        <svg viewBox="0 0 200 200" class="seal-svg">
                            <circle cx="100" cy="100" r="92" stroke="#dc2626" stroke-width="5" fill="none"/>
                            <circle cx="100" cy="100" r="82" stroke="#dc2626" stroke-width="2" fill="none"/>
                            <polygon points="100,66.9 107.5,88.8 130,88.8 111.2,101.2 118.8,123.1 100,109.4 81.2,123.1 88.8,101.2 70,88.8 92.5,88.8" fill="#dc2626"/>
                            <path id="seal-curve" d="M 42,105 A 58,58 0 1,1 158,105" fill="none" />
                            <text fill="#dc2626" font-family="'SimHei', 'Heiti SC', sans-serif" font-weight="bold" font-size="21" letter-spacing="3">
                                <textPath href="#seal-curve" startOffset="50%" text-anchor="middle">新中市居委会印</textPath>
                            </text>
