    </div>

    <!-- 彻底作用域化逻辑 -->
    <script>
        setTimeout(() => {
            const containers = document.querySelectorAll('.generator-container');
            const root = containers[containers.length - 1];
                          if (!root) return;
              /* 2026-10-12 修：原来 initialized 先置 true、click 委托挂在函数最末尾，
                 中途一旦出错就永远早退 → 监听永远挂不上 → 印章点了没反应。
                 现在把挂监听提到早退之前，用独立标记保证幂等。 */
              if (!root.dataset.hpClickBound) {
                root.dataset.hpClickBound = 'true';
              root.addEventListener('click', function(e) {
                  const backBtn = e.target.closest('.back-btn');
                  const nextBtn = e.target.closest('.btn-primary') || e.target.closest('#start-game');

                  if (backBtn) {
                      navigateTo(backBtn.dataset.target);
                  } else if (nextBtn && !nextBtn.disabled) {
                      if (nextBtn.id === 'start-game') {
                          setTimeout(() => startGame(), 260);   /* 松手即盖下：只留一点顿挫 */
                      } else {
                          const targetScreen = nextBtn.id.replace('to-', 'screen-');
                           if(root.querySelector('#' + targetScreen)) {
                              navigateTo(targetScreen);
                           }
                       }
                  }
              });
              }
              if (root.dataset.initialized) return;
              root.dataset.initialized = 'true';

            // ═══ 2026-10-11 新增：表单联动 + 查世界书自动填充 ═══
            try{   // 整块保护：出任何错都不许中断后面的声明
            const $=(sel)=>root.querySelector(sel);
            let hpNameConfirmed='';   // 已确认过的姓名（改了姓名就作废）
            let hpDupName='';          // 查重名命中的姓名（非空=重名，警告优先显示）
            let hpDupInfo='';          // 重名提示里的书名/条目说明

            // 【③ 年龄段由年龄自动推导】跳级只允许"年龄小但学段高"，不允许反向
            function hpSyncAgeGroup(){
                const el=$('#char-age'), out=$('#char-age-group');
                if(!el||!out) return;
                const hint=$('#age-group-hint');
                const sv=$('#char-is-student');
                const isStu = !!(sv && sv.value==='是');
                // ① 在校学生 + 已选年级 → 以【年级】为准（跳级一律以年级为准，不受年龄限制）
                if(isStu){
                    const gv=$('#char-grade');
                    const gr = gv ? String(gv.value||'') : '';
                    let band='';
                    if(/^小/.test(gr)) band='小学';
                    else if(/^初/.test(gr)) band='初中部';
                    else if(/^高/.test(gr)) band='高中部';
                    else if(/^大/.test(gr)) band='大学部';
                    if(band){
                        out.value=band;
                        if(hint) hint.textContent='在校学生：以所填「年级 '+gr+'」为准 → 年龄段「'+band+'」（跳级按年级算，不受年龄限制）。';
                        return;
                    }
                }
                // ② 其余情况按年龄估算
                const age=parseInt(el.value,10);
                if(!age||age<1||age>200){ out.value=''; if(hint) hint.textContent='按上面的「年龄」自动判定；在校学生选好「年级」后以年级为准。'; return; }
                let g;
                if(age<=5) g='幼儿园'; else if(age<=11) g='小学';
                else if(age<=15) g='初中部'; else if(age<=18) g='高中部';
                else if(age<=22) g='大学部'; else g='社会人';
                out.value=g;
                if(hint) hint.textContent='按年龄 '+age+' 估算为「'+g+'」。'+((sv&&sv.value==='是')?'（在校学生选好「年级」后会以年级为准）':'');
            }

            // 【④ 学生开关】
            function hpSyncStudent(){
                const v=$('#char-is-student');
                if(!v) return;
                const show=(v.value==='是');
                ['#grade-class-row','#grade-class-row2'].forEach((s)=>{
                    const e=$(s); if(e) e.style.display=show?'block':'none';
                });
                // ⚠ 大学部名册只有「大一学生/大二学生」，没有班级字母 —— 年级是「大X」时不显示班级，
                //    免得玩家被迫选一个 A~L 的班，档案里写出名册匹配不到的班级（玩家报座位只剩自己）
                try{
                    const gr=$('#char-grade'), r2=$('#grade-class-row2');
                    const isUni = !!(gr && /^大/.test(String(gr.value||'')));
                    if(r2 && show && isUni) r2.style.display='none';
                    if(isUni && gr){ const cl=$('#char-class'); if(cl) cl.value=''; }
                }catch(e){}
                // 在校学生：职业自动=学生并锁住（本职就是学生）；非学生：职业自由选
                const js=$('#char-occupation');
                if(js){
                    const so=Array.prototype.find.call(js.options,function(o){ return o.value==='学生'; });
                    if(so){ so.hidden=!show; so.disabled=!show; }
                    if(show){
                        js.value='学生';
                        js.disabled=true;
                        js.style.background='rgba(226,240,255,0.95)';
                        js.style.cursor='not-allowed';
                        js.title='在校学生的本职就是学生；有打工请填下面的「兼职」';
                    } else {
                        js.disabled=false;
                        js.style.background='';
                        js.style.cursor='';
                        js.title='';
                        if(js.value==='学生') js.value='';
                    }
                }
                // 兼职/副业：学生与社会人都显示（标签随身份变）
                const pt=$('#group-parttime');
                if(pt) pt.style.display='';
                const pl=$('#lb-parttime');
                if(pl) pl.textContent = show ? '兼职（选填）' : '副业 / 兼职（选填）';
                const pe=$('#char-parttime');
                if(pe) pe.placeholder = show
                    ? '如：便利店夜班 / 家庭教师（本职仍是学生，没有就留空）'
                    : '如：周末摄影师 / 网店店主（主业之外的副业，没有就留空）';
                // 非学生 → 清空年级/班级（避免写进档案）
                if(!show){
                    const gr=$('#char-grade'), cl=$('#char-class');
                    if(gr) gr.value='';
                    if(cl) cl.value='';
                }
                try{ hpSyncAgeGroup(); }catch(e){}
            }

            // 【⑨⑪ 按性别切换私密字段】
            function hpSyncGender(){
                const g=($('#char-gender')||{}).value||'';
                const lbl=$('#genital-label'), ta=$('#char-genital-data');
                if(lbl) lbl.textContent = (g==='女') ? '阴部数据' : '性器数据';
                if(ta&&ta.dataset){
                    ta.placeholder = (g==='女')
                        ? '如：形状、颜色、阴毛浓密程度、是否有过经历等。'
                        : '如：尺寸、包皮、颜色等。';
                }
                // 胸部 / 排斥 只在女性时显示
                [['#char-chest-data','女'],['#char-dislikes','女']].forEach(([sel,showWhen])=>{
                    const e=$(sel); if(!e) return;
                    const grp=e.closest?e.closest('.input-group'):null;
                    if(grp) grp.style.display=(g===showWhen)?'':'none';
                });
            }

            // 【⑩ 开局情境随机生成】
            const HP_OPEN_POOL=[
                '开学第一天的早晨，主角从自己家出发，路上遇见同路的同学，一路聊到校门口。',
                '放学后的傍晚，主角独自留在教室里，被一个意想不到的人叫住。',
                '周末午后，主角在玲雅广场闲逛，遇到一个正在发愁的人。',
                '雨天的电车站，主角没带伞，和同样在等车的人共用了一段屋檐。',
                '深夜的便利店，主角值夜班，凌晨进来一个看起来很累的客人。',
                '主角刚搬进新住处，正在收拾箱子，邻居来敲门打招呼。',
                '体育课后的更衣室走廊，主角抱着器材，和一个同学撞了个满怀。',
                '社团招新日，主角被好几个社团拉着填表，最后被一个人解围。'
            ];
            function hpRandomScenario(){
                const ta=$('#scenario-initial');
                if(!ta) return;
                ta.value=HP_OPEN_POOL[Math.floor(Math.random()*HP_OPEN_POOL.length)];
                ta.focus();
            }

            // 【① 查世界书：已有角色 → 自动填入并锁定，未涉及的自填】
            const HP_LOCKED=[];
            function hpLockField(sel,val,note){
                const e=$(sel); if(!e||!val) return false;
                if(e.tagName==='SELECT'){
                    const ok=[...e.options].some(o=>o.value===val||o.textContent.trim()===val);
                    if(!ok) return false;
                }
                e.value=val;
                e.readOnly=true; e.disabled=true;
                e.style.background='rgba(226,240,255,0.95)';
                e.style.cursor='not-allowed';
                e.title=note||'来自角色卡已有设定，已锁定';
                HP_LOCKED.push(sel);
                return true;
            }
            // 世界书里的 race/gender 常写英文 → 映射成中文再填
            // 世界书里的 Occupation 是长串（"新中市国立学校初三A班学生"）→ 按关键词归到下拉选项
            function hpMapJob(v){
                const s=String(v||'').trim();
                if(!s) return '';
                const R=[
                    [/学生|就读|在校生/,                     '学生'],
                    [/老师|教师|教员|讲师|教授|实习.*教师/,   '教师'],
                    [/护士|医生|医师|药剂|医护/,              '医护人员'],
                    [/店员|服务生|服务员|收银|便利店/,        '店员 / 服务生'],
                    [/教练|健身/,                            '自由职业'],
                    [/职员|员工|社员|公司|集团|事务所/,       '公司职员'],
                    [/无业|待业|自由/,                       '自由职业'],
                ];
                for(const [re,val] of R){ if(re.test(s)) return val; }
                return '';
            }
            function hpMapRace(v){
                const s=String(v||'').trim();
                const M={'human':'人类','人类':'人类','elf':'精灵','精灵':'精灵','demon':'魔族','devil':'魔族','魔族':'魔族',
                    'vampire':'吸血鬼','吸血鬼':'吸血鬼','dragon':'龙族','龙族':'龙族','beast':'兽人','兽人':'兽人',
                    'android':'人造人','robot':'机械','机械':'机械','ghost':'幽灵','spirit':'灵体','god':'神族','神族':'神族',
                    'half-elf':'半精灵','half elf':'半精灵','angel':'天使','天使':'天使','orc':'兽人'};
                return M[s.toLowerCase()] || s;
            }
            function hpMapGender(v){
                const s=String(v||'').trim();
                const M={'male':'男','m':'男','man':'男','boy':'男','男':'男',
                    'female':'女','f':'女','woman':'女','girl':'女','女':'女','female (trans)':'女'};
                return M[s.toLowerCase()] || s;
            }
            // 世界书里"家庭情况"常写成 relationship: 列表 → 取前几行拼成一句
            async function hpApplyResidence(name){
                try{
                    const v=await hpLookupResidence(name);
                    if(!v) return;
                    const e=$('#char-residence');
                    if(!e) return;
                    const opt=[...e.options].find(function(o){ return o.value===v||o.value.indexOf(v)>=0||o.textContent.indexOf(v)>=0; });
                    if(opt){ e.value=opt.value; }
                    else { e.value=v; }
                    e.disabled=true; e.style.background='rgba(226,240,255,0.95)'; e.style.cursor='not-allowed';
                    e.title='来自世界书「住宅」条目';
                }catch(e){}
            }
            // 【居住地】角色条目里没有住址字段，要去「住宅·xxx区」三条里按名字找所在段落
            async function hpLookupResidence(name){
                const books=(window.__hpBooks&&window.__hpBooks.length)?window.__hpBooks:[];
                const KEYS=['住宅','居住','公寓','社区'];
                const OPTS=['山海雅苑','明日之墅','红叶庄','平安公寓','千年公寓','樱花庄','玲雅集团顶楼','自建房区','林家宅邸','无固定居所'];
                for(const b of books){
                    let es=null; try{ es=await hpEntriesOf(b); }catch(e){ es=null; }
                    if(!Array.isArray(es)) continue;
                    for(const e of es){
                        const cm=String(e.comment||e.name||'');
                        if(!KEYS.some(function(k){ return cm.indexOf(k)>=0; })) continue;
                        const ct=String(e.content||'');
                        const i=ct.indexOf(name);
                        if(i<0) continue;
                        // 取该名字之前最近的一个小节标题
                        const before=ct.slice(0,i);
                        const hs=before.match(/【([^】]{2,24})】/g)||[];
                        let head=hs.length?hs[hs.length-1].replace(/[【】]/g,''):'';
                        if(!head){ const m=before.match(/([山海明红平千樱玲自林无][^\n，。、]{1,14}(?:区|苑|墅|庄|公寓|顶楼|宅邸))/); if(m) head=m[1]; }
                        const isFixed=/公寓|宿舍|无固定|借住|流浪|网吧|露宿/.test(ct.slice(i,i+120));
                        if(isFixed) return '无固定居所';
                        // 按段落标题映射到下拉选项
                        for(const o of OPTS){ if(head.indexOf(o)>=0) return o; }
                        if(/自建|独户|一户建/.test(head+ct.slice(Math.max(0,i-200),i))) return '自建房区';
                        if(head) return head;
                    }
                }
                return '';
            }
            function hpApplyStudent(t){
                const stu=hpDetectStudent(t);
                if(!stu) return;
                const el=$('#char-is-student');
                if(el){ el.value='是'; el.disabled=true; el.style.background='rgba(226,240,255,0.95)'; }
                hpSyncStudent();
                if(stu.grade) hpLockField('#char-grade',stu.grade,'来自角色卡设定');
                if(stu.cls)   hpLockField('#char-class',stu.cls,'来自角色卡设定');
                if(stu.occ && !($('#char-occupation')||{}).value) { const j=$('#char-occupation'); if(j) j.value='学生'; }
            }
            // 【学生识别】从条目里读 Occupation 与正文，判断是否学生并抽年级/班级
            function hpDetectStudent(t){
                const s=String(t||'');
                const occ=hpPick(s,['Occupation','职业'],80)||'';
                const gradeRe='(初一|初二|初三|高一|高二|高三|大一|大二|大三|大四)';
                const isStu = /学生|国立学校|在校|就读/.test(occ)
                           || new RegExp(gradeRe).test(s)
                           || /小学|初中部|高中部|大学部|幼儿园/.test(s);
                if(!isStu) return null;
                let grade='';
                const g=s.match(new RegExp(gradeRe));
                if(g) grade=g[1];
                if(!grade && /初中部/.test(s+occ)) grade='初一';
                if(!grade && /高中部/.test(s+occ)) grade='高一';
                if(!grade && /大学部/.test(s+occ)) grade='大一';
                let cls='';
                const c=s.match(new RegExp(gradeRe+'\\s*([A-L])\\s*班?'));
                if(c && c[2]) cls=c[2]+'班';   // c[1]=年级组, c[2]=字母
                return { grade:grade, cls:cls, occ:occ };
            }
            function hpPickFamily(t){
                let v=hpPick(t,['家庭情况','家庭','family'],200);
                if(v) return v;
                const m=String(t).match(/relationship[ \t]*[:：][ \t]*\n([\s\S]{0,600}?)(\n[ \t]*[A-Za-z\u4e00-\u9fa5]{2,10}[ \t]*[:：]|$)/);
                if(!m) return '';
                const lines=String(m[1]).split('\n').map(function(x){ return x.replace(/^[\s\-•·]+/,'').trim(); })
                    .filter(function(x){ return x && !/^[-—]+$/.test(x); }).slice(0,8);
                return lines.join('；');
            }
            function hpPick(text, keys, maxLen){
                const L=maxLen||80;
                for(const k of keys){
                    // 冒号后只吃空格/制表符，不吃换行 —— 否则会串到下一行（把子字段标签也吞进来）
                    const m=String(text).match(new RegExp(k+'[ \\t]*[:：][ \\t]*([^\\n\\r]{1,'+L+'})'));
                    if(m){
                        let v=m[1].trim()
                            // 去掉值开头的子字段标签（如 "facial feature:" / "daily_wear:" / "race:"）
                            .replace(/^[A-Za-z_][A-Za-z0-9_ ]{0,24}[ \t]*[:：][ \t]*/,'')
                            .replace(/^["「『]|["」』]$/g,'')
                            .trim();
                        if(v && v!=='—' && v!=='未描述' && v!=='无') return v;
                    }
                }
                return '';
            }
            function hpSetStatus(msg,color){
                const st=$('#status-text');
                if(st){ st.textContent=msg; if(color) st.style.color=color; }
            }
            // 【环境诊断】把关键 API 的真实情况显示在页面上
            function hpEnvDiag(){
                const L=[];
                let SG=null,CTX=null;
                try{ SG=window.SillyTavern||(window.top&&window.top.SillyTavern)||null; }catch(e){}
                try{ CTX=SG&&SG.getContext?SG.getContext():null; }catch(e){}
                const TH=window.TavernHelper||(window.top&&window.top.TavernHelper)||null;
                L.push('SillyTavern: '+(SG?'有':'无'));
                L.push('getContext: '+(CTX?'有':'无'));
