            // 诊断确认：拿到的书名带「」引号 → 必须清洗才能被 API 认
            function hpCleanBookName(n){
                let x=String(n==null?'':n);
                for(let i=0;i<4;i++){
                    const y=x.trim()
                        .replace(/^[\s"'\`「『【\[\]\\]+/,'')
                        .replace(/[\s"'\`」』】\[\]\\]+$/,'');
                    if(y===x) break;
                    x=y;
                }
                return x.trim();
            }
            async function hpEntriesOf(book){
                const B=hpCleanBookName(book);   // 清洗后的真名
                const TH=window.TavernHelper||(window.top&&window.top.TavernHelper)||null;
                const SG=window.SillyTavern||(window.top&&window.top.SillyTavern)||null;
                let CTX=null; try{ CTX=SG&&SG.getContext?SG.getContext():null; }catch(e){}
                // ★ 诊断确认存在的 API：先用 TavernHelper 取名（并清洗「」）
                if(TH){
                    for(const fn of ['getGlobalWorldbookNames','getWorldbookNames']){
                        if(typeof TH[fn]!=='function') continue;
                        try{ const v=await TH[fn]();
                             if(v){ (Array.isArray(v)?v:[v]).forEach(function(x){ const nn=hpCleanBookName(x); if(nn&&!seen[nn]){seen[nn]=1;out.push(nn);} }); diag.push(fn+' → '+JSON.stringify(v).slice(0,60)); }
                        }catch(e){ diag.push(fn+' ✗ '+((e&&e.message)||e)); }
                    }
                    if(out.length){ window.__hpKjDiag=diag; return out; }
                }
                // ① 酒馆标准 API：ctx.loadWorldInfo(书名) → { entries:{...} }
                if(CTX&&typeof CTX.loadWorldInfo==='function'){
                    try{
                        const d=await CTX.loadWorldInfo(B);
                        const ent=d&&d.entries?d.entries:(d&&d[0]&&d[0].entries?d[0].entries:null);
                        if(ent){ const arr=Array.isArray(ent)?ent:Object.values(ent); if(arr&&arr.length) return arr; }
                    }catch(e){ window.__hpReadErr='loadWorldInfo: '+((e&&e.message)||e); }
                }
                // ② 酒馆助手
                if(TH){
                    for(const fn of ['getWorldbook','getLorebookEntries','getWorldbookEntries']){
                        if(typeof TH[fn]!=='function') continue;
                        try{ const r=await TH[fn](B); if(Array.isArray(r)&&r.length) return r; }catch(e){ window.__hpReadErr=fn+': '+((e&&e.message)||e); }
                    }
                }
                return null;
            }
            async function hpBooksInline(){
                const out=[],seen={},diag=[];
                const add=(raw)=>{ String(raw==null?'':raw).split(/[,\n]/).map(x=>x.trim().replace(/^"|"$/g,'')).filter(Boolean).forEach(n=>{ if(!seen[n]){seen[n]=1;out.push(n);} }); };
                const TH=window.TavernHelper||(window.top&&window.top.TavernHelper)||null;
                const SG=window.SillyTavern||(window.top&&window.top.SillyTavern)||null;
                let CTX=null; try{ CTX=SG&&SG.getContext?SG.getContext():null; }catch(e){}
                if(CTX){
                    try{ const pu=CTX.powerUser||CTX.power_user; const g=pu&&pu.world_info&&pu.world_info.globalSelect;
                         if(Array.isArray(g)&&g.length){ add(g.join('\n')); diag.push('全局 globalSelect → '+g.length); } else diag.push('globalSelect → 空'); }catch(e){ diag.push('globalSelect ✗ '+((e&&e.message)||e)); }
                    try{ if(Array.isArray(CTX.world_names)&&CTX.world_names.length){ add(CTX.world_names.join('\n')); diag.push('world_names → '+CTX.world_names.length); } }catch(e){}
                } else diag.push('getContext 取不到');
                if(out.length){ window.__hpKjDiag=diag; return out; }
                for(const cmd of ['/getcharbook type=all','/getglobalbooks','/getchatbook create=false','/getcharbook']){
                    try{ const r=await triggerSlash(cmd); add(r); diag.push(cmd+' → '+(String(r||'').length)); }
                    catch(e){ diag.push(cmd+' ✗ '+((e&&e.message)||e)); }
                }
                if(!out.length&&TH){
                    for(const fn of ['getWorldbookNames','getAllWorldbookNames','getWorldbookNameList']){
                        if(typeof TH[fn]!=='function'){ diag.push('TH.'+fn+' 无'); continue; }
                        try{ const v=await TH[fn](); add(Array.isArray(v)?v.join('\n'):v); diag.push('TH.'+fn+' → ok'); }catch(e){ diag.push('TH.'+fn+' ✗ '+((e&&e.message)||e)); }
                    }
                }
                window.__hpKjDiag=diag;
                return out;
            }
            async function hpLookupCharacter(){
                const nm=($('#char-name')||{}).value;
                if(!nm||!nm.trim()){ hpSetStatus('请先填写姓名','#dc2626'); return; }
                const name=nm.trim();
                const hint=$('#char-lookup-hint');
                if(hint) hint.textContent='正在查找「'+name+'」……';
                hpSetStatus('正在世界书里查找「'+name+'」……');
                let books=[];
                try{ books = (typeof hpCandidateBooks==='function') ? await hpCandidateBooks() : await hpBooksInline(); }catch(e){ window.__hpKjErr=String((e&&e.message)||e); try{ books=await hpBooksInline(); }catch(e2){} }
                // ★ 消费点清洗：无论书名从哪来，这里统一剥掉 ["…"] 「」 \ 等包裹字符
                try{ books = books.map(function(x){ let v=String(x==null?'':x); for(let i=0;i<4;i++){ const y=v.trim().replace(/^[\s"'`「『【\[\]\\]+/,'').replace(/[\s"'`」』】\[\]\\]+$/,''); if(y===v) break; v=y; } return v.trim(); }).filter(Boolean); }catch(e){}
                if(!books.length){ hpShowDiag('未取到世界书名 · 环境诊断'); hpSetStatus('未取到世界书名','#dc2626'); return; }
                const TH=window.TavernHelper||(window.top&&window.top.TavernHelper);
                let hit=null;
                window.__hpBooks=books.slice(0,8); window.__hpEntryCounts=[];
                for(const b of books){
                    // ① 首选：TavernHelper 直接拿整本书的条目（能同时查备注与正文）
                    let es=null;
                    try{ es=await hpEntriesOf(b); }catch(e){ es=null; }
                    try{ window.__hpEntryCounts.push(b+' → '+((es&&es.length)||0)+' 条'); }catch(e){}
                    if(Array.isArray(es)&&es.length){
                        const byC=es.find((e)=>String(e.comment||'').indexOf(name)>=0);
                        const byT=byC||es.find((e)=>String(e.content||'').replace(/[\s　]/g,'').indexOf(name)>=0);
                        if(byT){ hit={book:b,uid:(byT.uid!=null?byT.uid:byT.id),cm:String(byT.comment||''),ct:String(byT.content||'')}; break; }
                        continue;
                    }
                    // ② 兜底：slash 命令按备注找
                    let uid='';
                    try{ uid=String(await triggerSlash('/findentry file="'+b+'" field=comment '+name)||'').trim(); }catch(e){ uid=''; }
                    if(!uid||uid==='undefined'||uid==='null') continue;
                    let cm='',ct='';
                    try{ cm=String(await triggerSlash('/getentryfield file="'+b+'" field=comment '+uid)||''); }catch(e){}
                    try{ ct=String(await triggerSlash('/getentryfield file="'+b+'" field=content '+uid)||''); }catch(e){}
                    cm=cm.replace(/^"|"$/g,'').trim(); ct=ct.replace(/^"|"$/g,'');
                    if(ct.indexOf(name)>=0){ hit={book:b,uid:uid,cm:cm,ct:ct}; break; }
                }
                if(!hit){
                    hpDupName='';
                    hpNameConfirmed=name;
                    hpUpdateNext();
                    return;
                }
                hpDupName=name;
                hpDupInfo='（《'+hit.book+'》'+(hit.cm?('「'+hit.cm+'」'):'')+'）';
                hpNameConfirmed='';
                hpUpdateNext();
            }

