                const hpJsonList = (raw) => {
                    const t = String(raw == null ? '' : raw).trim();
                    if (!t) return [];
                    if (t.charAt(0) === '[') {
                        try {
                            let a; try { a = JSON.parse(t); } catch (e) { return; }
                            if (Array.isArray(a)) return a.map((x) => String(x).trim().replace(/^[\s"'`「『【\[\]]+/,'').replace(/[\s"'`」』】\[\]]+$/,'')).filter(Boolean);
                        } catch (e) {}
                    }
                    return t.split(/[,\n]/).map((x) => x.trim().replace(/^[\s"'`「『【\[\]]+/,'').replace(/[\s"'`」』】\[\]]+$/,'')).filter(Boolean);
                };
                const hpCandidateBooks = async () => {
                    const out = [], seen = {}, diag = [];
