                            const g = pu && pu.world_info && pu.world_info.globalSelect;
                            if (Array.isArray(g) && g.length) { push(g.join('\n')); diag.push('全局世界书 globalSelect → ' + g.length); }
                        } catch (e) { diag.push('globalSelect ✗ ' + ((e && e.message) || e)); }
                        try {
                            if (Array.isArray(CTX.world_names) && CTX.world_names.length) { push(CTX.world_names.join('\n')); diag.push('ctx.world_names → ' + CTX.world_names.length); }
                        } catch (e) {}
                    }
                    if (out.length) { window.__hpKjDiag = diag; return out; }

                    // ① slash 命令（原有路径）
                    for (const cmd of ['/getcharbook type=all', '/getglobalbooks', '/getchatbook create=false']) {
                        try { const r = await triggerSlash(cmd); push(r); diag.push(cmd + ' → ' + (hpJsonList(r).length || 0)); }
                        catch (e) { diag.push(cmd + ' ✗ ' + ((e && e.message) || e)); }
