                    window.__hpKjDiag = diag;
                    if (!out.length) console.warn('[新中市] 取世界书名失败，诊断：\n' + diag.join('\n'));
                    return out;
                    }catch(_e){
                        diag.push('★ 整体异常：' + ((_e && _e.message) || _e));
                        window.__hpKjErr = String((_e && _e.message) || _e);
