  };
  function hpSyncClassOptions(){
    try{
      var g = document.querySelector('#char-grade'), c = document.querySelector('#char-class');
      if(!g || !c) return;
      var list = HP_CLS_BY_GRADE[String(g.value||'').trim()];
      if(list === undefined) return;                  // 不认识的年级 → 一个字都不动
      var want = list.join('|');
      if(c.__hpWant === want) return;                 // 选项没变 → 不重建（免得打断已打开的下拉）
      var keep = c.value;
      c.__hpWant = want;
      c.innerHTML = list.map(function(x){ return '<option value="'+x+'">'+x+'</option>'; }).join('');
      if(list.indexOf(keep) >= 0) c.value = keep;     // 原来选的还在 → 保留
      else if(list.length) c.value = list[0];
