  if(!window.__hpClassSync){
    window.__hpClassSync = 1;
    document.addEventListener('change', function(e){
      var t = e.target;
      if(t && t.id === 'char-grade') setTimeout(hpSyncClassOptions, 0);
    }, true);
    setInterval(hpSyncClassOptions, 800);             // 表单重建后也能跟上（选项没变时什么都不做）
  }
